[1,2,6],[2,3],[2],[5],[0],[8,9,15],[4,11,14],[4,5,10,11,12,14],[11],[2,11],[4,9,15,16],[4,14],[],[1,5],[4,9,15],[],[14],[13,14],[0,6,8,12],[1,4,11],[],[],[16],[11],[7,10,12],[0,6],[16]
]
h,w=len(rows),18
g=[[9]*w for _ in range(h)]
for r,cs in enumerate(rows):
    for c in cs:g[r][c]=0
# Paint interior cells between same-colored dots on rows or columns.
for r in range(h):
    cs=rows[r]
    if len(cs)>=2:
        for c in range(min(cs),max(cs)+1):
            if g[r][c]==9:g[r][c]=3
