print('\n'.join('['+','.join(map(str,r))+'],' for r in g))

import json
rows = [
[1,2,6],[2,3],[2],[5],[0],[8,9,15],[4,11,14],[4,5,10,11,12,14],[11],[2,11],[4,9,15,16],[4,14],[],[1,5],[4,9,15],[],[14],[13,14],[0,6,8,12],[1,4,11],[],[],[16],[11],[7,10,12],[0,6],[16]
]
h,w=len(rows),18
g=[[9]*w for _ in range(h)]
for r, cs in enumerate(rows):
    for c in cs: g[r][c]=0
# Fill only gaps between adjacent original markers horizontally and vertically.
for r, cs in enumerate(rows):
    for a,b in zip(cs,cs[1:]):
        for c in range(a+1,b):
            g[r][c]=3
for c in range(w):
    rs=[r for r in range(h) if c in rows[r]]
    for a,b in zip(rs,rs[1:]):
        for r in range(a+1,b):
            if g[r][c]==9: g[r][c]=3
assert len(g)==27 and all(len(r)==18 for r in g)
assert all(type(v) is int and 0<=v<=9 for row in g for v in row)
print(json.dumps(g,separators=(',',':')))
print('VALID',len(g),len(g[0]),[len(r) for r in g])
